//! Counterexample schedules: strict replay, completion, minimization and
//! rendering.
//!
//! A *schedule* is the sequence of transitions chosen by the scheduler. It is
//! the only artifact the explorer produces for a violation; the readable
//! witness is regenerated by replaying it with recording on, so that every
//! line of a witness comes from a transition the model executed.

use std::collections::BTreeMap;

use serde::{Deserialize, Serialize};

use crate::engine::{Event, EventKind, Recorder, apply, enabled, initial_state, is_quiescent};
use crate::explore::Counterexample;
use crate::invariant::{Invariant, When};
use crate::model::Model;
use crate::state::{Outcome, State, TKind, Transition};
use crate::value::{Row, Value};

#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
#[error("transition {index} ({transition:?}) is not enabled: {reason}")]
pub struct ReplayError {
    pub index: usize,
    pub transition: Transition,
    pub reason: String,
}

pub struct Replayed {
    pub state: State,
    pub steps: Vec<(Transition, Vec<Event>)>,
    /// Index (exclusive end) of the shortest prefix that violates an
    /// `always` invariant, if any.
    pub always_violation: Option<(usize, String)>,
}

/// Replay `schedule` strictly: every transition must be enabled when taken.
pub fn replay(
    model: &Model,
    schedule: &[Transition],
    record: bool,
) -> Result<Replayed, ReplayError> {
    let mut s = initial_state(model);
    let mut steps = Vec::new();
    let mut always_violation = None;
    for (i, t) in schedule.iter().enumerate() {
        if !enabled(model, &s).contains(t) {
            return Err(ReplayError {
                index: i,
                transition: *t,
                reason: "not in the set of enabled transitions".into(),
            });
        }
        let mut rec = if record {
            Recorder::on()
        } else {
            Recorder::off()
        };
        let applied = apply(model, &s, *t, &mut rec).map_err(|u| ReplayError {
            index: i,
            transition: *t,
            reason: format!("unsupported: {}", u.detail),
        })?;
        s = applied.state;
        steps.push((*t, rec.events));
        if always_violation.is_none() {
            for inv in model.invariants.iter().filter(|i| i.when == When::Always) {
                if !inv.holds(model, &s) {
                    always_violation = Some((i + 1, inv.name.clone()));
                    break;
                }
            }
        }
    }
    Ok(Replayed {
        state: s,
        steps,
        always_violation,
    })
}

/// Extend a schedule to a quiescent state by running the lowest enabled
/// `Step`/`Resume` transition (never a crash or retry). `None` if the system
/// gets stuck.
pub fn complete(model: &Model, state: &State) -> Option<Vec<Transition>> {
    let mut s = state.clone();
    let mut out = Vec::new();
    loop {
        let en = enabled(model, &s);
        if is_quiescent(model, &en) {
            return s.is_finished().then_some(out);
        }
        let t = en
            .iter()
            .copied()
            .find(|t| matches!(t.kind, TKind::Step | TKind::Resume | TKind::Deadlock))
            .or_else(|| {
                en.iter().copied().find(|t| {
                    t.kind == TKind::Retry
                        && model.actors[t.actor as usize]
                            .retry
                            .as_ref()
                            .is_some_and(|r| r.guaranteed)
                })
            })?;
        s = apply(model, &s, t, &mut Recorder::off()).ok()?.state;
        out.push(t);
        if out.len() > 10_000 {
            return None;
        }
    }
}

/// [`complete`] for the `termination` invariant: the run may end in a state
/// that is quiescent but not finished (stuck).
fn complete_stuck(model: &Model, state: &State) -> Option<Vec<Transition>> {
    let mut s = state.clone();
    let mut out = Vec::new();
    loop {
        let en = enabled(model, &s);
        if is_quiescent(model, &en) {
            return Some(out);
        }
        let t = en
            .iter()
            .copied()
            .find(|t| {
                matches!(
                    t.kind,
                    TKind::Step | TKind::Resume | TKind::Deadlock | TKind::ServerComplete
                )
            })
            .or_else(|| {
                en.iter().copied().find(|t| {
                    t.kind == TKind::Retry
                        && model.actors[t.actor as usize]
                            .retry
                            .as_ref()
                            .is_some_and(|r| r.guaranteed)
                })
            })?;
        s = apply(model, &s, t, &mut Recorder::off()).ok()?.state;
        out.push(t);
        if out.len() > 10_000 {
            return None;
        }
    }
}

fn find_invariant<'a>(model: &'a Model, name: &str) -> Option<&'a Invariant> {
    model.invariants.iter().find(|i| i.name == name)
}

/// If `schedule` (completed to quiescence for `final` invariants) violates
/// the named invariant, return the effective schedule.
pub fn check_schedule(
    model: &Model,
    schedule: &[Transition],
    invariant: &str,
) -> Option<Vec<Transition>> {
    let inv = find_invariant(model, invariant)?;
    let r = replay(model, schedule, false).ok()?;
    match inv.when {
        When::Always => {
            // The shortest violating prefix.
            let mut s = initial_state(model);
            if !inv.holds(model, &s) {
                return Some(Vec::new());
            }
            for (i, t) in schedule.iter().enumerate() {
                s = apply(model, &s, *t, &mut Recorder::off()).ok()?.state;
                if !inv.holds(model, &s) {
                    return Some(schedule[..=i].to_vec());
                }
            }
            None
        }
        When::Final => {
            let mut full = schedule.to_vec();
            if inv.name == crate::model::TERMINATION {
                full.extend(complete_stuck(model, &r.state)?);
            } else {
                full.extend(complete(model, &r.state)?);
            }
            let end = replay(model, &full, false).ok()?;
            (!inv.holds(model, &end.state)).then_some(full)
        }
    }
}

/// Phase 9: how late the server completes the operations it held (the sum
/// of the positions of its completions). Of two equally short schedules the
/// one with the earlier completions is the simpler explanation.
pub fn completion_delay(schedule: &[Transition]) -> usize {
    schedule
        .iter()
        .enumerate()
        .filter(|(_, t)| t.kind == TKind::ServerComplete)
        .map(|(i, _)| i)
        .sum()
}

pub fn context_switches(schedule: &[Transition]) -> usize {
    let mut n = 0;
    let mut last: Option<(u16, u16)> = None;
    for t in schedule {
        if matches!(t.kind, TKind::Step | TKind::Resume | TKind::Deadlock) {
            let who = (t.actor, t.thread);
            if last.is_some_and(|l| l != who) {
                n += 1;
            }
            last = Some(who);
        }
    }
    n
}

/// Greedily shorten the schedule and reduce its context switches while
/// every candidate is validated by replay and still violates the same
/// invariant.
pub fn minimize(model: &Model, ce: &Counterexample) -> Vec<Transition> {
    let Some(mut best) = check_schedule(model, &ce.schedule, &ce.invariant) else {
        return ce.schedule.clone();
    };
    let better = |a: &[Transition], b: &[Transition]| {
        (a.len(), context_switches(a), completion_delay(a))
            < (b.len(), context_switches(b), completion_delay(b))
    };
    let mut budget = 4000usize;
    loop {
        let mut improved = false;
        // 1. Delete single transitions.
        for i in (0..best.len()).rev() {
            if budget == 0 {
                return best;
            }
            budget -= 1;
            let mut cand = best.clone();
            cand.remove(i);
            if let Some(eff) = check_schedule(model, &cand, &ce.invariant)
                && better(&eff, &best)
            {
                best = eff;
                improved = true;
                break;
            }
        }
        if improved {
            continue;
        }
        // 2. Swap adjacent transitions of different tasks to merge runs.
        for i in 0..best.len().saturating_sub(1) {
            if budget == 0 {
                return best;
            }
            // The server completing a held operation is not a step of the
            // actor that submitted it.
            let who = |t: &Transition| (t.actor, t.thread, t.kind == TKind::ServerComplete);
            if who(&best[i]) == who(&best[i + 1]) {
                continue;
            }
            budget -= 1;
            let mut cand = best.clone();
            cand.swap(i, i + 1);
            if let Some(eff) = check_schedule(model, &cand, &ce.invariant)
                && better(&eff, &best)
            {
                best = eff;
                improved = true;
                break;
            }
        }
        if !improved {
            return best;
        }
    }
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct WitnessStep {
    pub index: usize,
    pub actor: String,
    pub kind: String,
    pub events: Vec<Event>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TermValue {
    pub term: String,
    pub value: Value,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct FinalSummary {
    pub tables: BTreeMap<String, Vec<Row>>,
    pub actors: Vec<(String, String)>,
    pub external_effects: Vec<String>,
    pub terms: Vec<TermValue>,
    /// Whether the state is quiescent (all tasks finished).
    pub quiescent: bool,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Witness {
    pub invariant: String,
    pub formula: String,
    pub when: When,
    pub initial_tables: BTreeMap<String, Vec<Row>>,
    pub steps: Vec<WitnessStep>,
    pub final_state: FinalSummary,
    pub context_switches: usize,
    pub minimized: bool,
    pub original_length: usize,
    #[serde(skip)]
    pub schedule: Vec<Transition>,
}

pub fn summarize(model: &Model, s: &State, inv: &Invariant) -> FinalSummary {
    let mut tables = BTreeMap::new();
    for (i, t) in model.schema.tables.iter().enumerate() {
        tables.insert(t.name.clone(), s.committed_rows(model, i as u16));
    }
    let actors = model
        .actors
        .iter()
        .zip(&s.actors)
        .map(|(spec, st)| {
            let mut label = st.outcome.label();
            if st.completions > 0 && !matches!(st.outcome, Outcome::Ok) {
                label = format!(
                    "{label} (returned normally {} time(s) earlier)",
                    st.completions
                );
            }
            (spec.name.clone(), label)
        })
        .collect();
    let external_effects = s
        .externals
        .iter()
        .map(|x| {
            format!(
                "{} by {}{}{}",
                x.channel,
                model.actors[x.actor as usize].name,
                x.key
                    .as_ref()
                    .map(|k| format!(" key={}", k.render()))
                    .unwrap_or_default(),
                if x.deduplicated {
                    " (deduplicated)"
                } else {
                    ""
                }
            )
        })
        .collect();
    let mut terms = Vec::new();
    inv.formula.visit_terms(&mut |t| {
        terms.push(TermValue {
            term: t.render(),
            value: t.eval(model, s),
        });
    });
    FinalSummary {
        tables,
        actors,
        external_effects,
        terms,
        quiescent: s.is_finished(),
    }
}

pub fn build_witness(model: &Model, ce: &Counterexample, minimize_it: bool) -> Option<Witness> {
    let original_length = ce.schedule.len();
    let schedule = if minimize_it {
        minimize(model, ce)
    } else {
        // Even an unminimized witness is completed and validated.
        check_schedule(model, &ce.schedule, &ce.invariant)?
    };
    let r = replay(model, &schedule, true).ok()?;
    let inv = find_invariant(model, &ce.invariant)?;
    if inv.holds(model, &r.state) {
        return None;
    }
    let steps = r
        .steps
        .iter()
        .enumerate()
        .map(|(i, (t, events))| WitnessStep {
            index: i + 1,
            actor: match t.kind {
                TKind::Crash | TKind::CrashInFlight => {
                    format!("process {}", model.process_names[t.thread as usize])
                }
                _ => model.actors[t.actor as usize].name.clone(),
            },
            kind: match t.kind {
                TKind::Step => "step",
                TKind::Resume => "resume",
                TKind::Crash => "crash",
                TKind::Retry => "retry",
                TKind::Deadlock => "deadlock",
                TKind::LostCommitted => "ack-lost-committed",
                TKind::LostNotCommitted => "ack-lost-not-committed",
                TKind::CrashInFlight => "crash-in-flight",
                TKind::ServerComplete => "server-complete",
            }
            .to_owned(),
            events: events.clone(),
        })
        .collect();
    let mut initial_tables = BTreeMap::new();
    for (i, t) in model.schema.tables.iter().enumerate() {
        initial_tables.insert(t.name.clone(), model.initial_rows[i].clone());
    }
    Some(Witness {
        invariant: inv.name.clone(),
        formula: inv.formula.render(),
        when: inv.when,
        initial_tables,
        steps,
        final_state: summarize(model, &r.state, inv),
        context_switches: context_switches(&schedule),
        minimized: minimize_it,
        original_length,
        schedule,
    })
}

/// A plain-text rendering in the style of the Phase 6 specification.
pub fn render_text(model: &Model, w: &Witness) -> String {
    let mut out = String::new();
    out.push_str(&format!("COUNTEREXAMPLE: {}\n\n", model.name));
    out.push_str("Initial state:\n");
    for (t, rows) in &w.initial_tables {
        if rows.is_empty() {
            out.push_str(&format!("  {t}: (no rows)\n"));
        }
        for r in rows {
            out.push_str(&format!("  {t}: {}\n", Value::Row(r.clone()).render()));
        }
    }
    out.push_str(&format!(
        "\nSchedule ({} transitions, {} context switches{}):\n\n",
        w.steps.len(),
        w.context_switches,
        if w.minimized {
            ", minimized and replayed"
        } else {
            ""
        }
    ));
    for s in &w.steps {
        for e in &s.events {
            if matches!(e.kind, EventKind::Resumed) {
                continue;
            }
            let at = e
                .src
                .as_ref()
                .map(|r| r.label())
                .filter(|l| !l.is_empty())
                .map(|l| format!("    [{l}]"))
                .unwrap_or_default();
            out.push_str(&format!(
                "  {:>3}  {:<8} {}{at}\n",
                s.index, s.actor, e.text
            ));
        }
    }
    out.push_str("\nFinal state:\n");
    for (t, rows) in &w.final_state.tables {
        if rows.is_empty() {
            out.push_str(&format!("  {t}: (no rows)\n"));
        }
        for r in rows {
            out.push_str(&format!("  {t}: {}\n", Value::Row(r.clone()).render()));
        }
    }
    for (a, o) in &w.final_state.actors {
        out.push_str(&format!("  actor {a}: {o}\n"));
    }
    for x in &w.final_state.external_effects {
        out.push_str(&format!("  external effect: {x}\n"));
    }
    out.push_str(&format!(
        "\nInvariant `{}` ({}):\n  {}\n",
        w.invariant,
        match w.when {
            When::Final => "final state",
            When::Always => "every state",
        },
        w.formula
    ));
    for t in &w.final_state.terms {
        out.push_str(&format!("    {} = {}\n", t.term, t.value.render()));
    }
    out.push_str("\nResult:\n  VIOLATED\n");
    out
}

/// Every complete schedule of the model (all interleavings, no state
/// merging, no reduction), up to `limit`. Used by differential tests, which
/// need *schedules*, not just states. Returns the schedules and whether the
/// limit cut the enumeration short.
pub fn enumerate_schedules(model: &Model, limit: usize) -> (Vec<Vec<Transition>>, bool) {
    fn go(
        model: &Model,
        s: &State,
        path: &mut Vec<Transition>,
        out: &mut Vec<Vec<Transition>>,
        limit: usize,
        truncated: &mut bool,
    ) {
        if out.len() >= limit {
            *truncated = true;
            return;
        }
        let en = enabled(model, s);
        if is_quiescent(model, &en) {
            if s.is_finished() {
                out.push(path.clone());
            }
            if en.is_empty() {
                return;
            }
        }
        if s.steps >= model.bounds.max_steps {
            *truncated = true;
            return;
        }
        for t in en {
            let Ok(a) = apply(model, s, t, &mut Recorder::off()) else {
                continue;
            };
            path.push(t);
            go(model, &a.state, path, out, limit, truncated);
            path.pop();
        }
    }
    let mut out = Vec::new();
    let mut truncated = false;
    go(
        model,
        &initial_state(model),
        &mut Vec::new(),
        &mut out,
        limit,
        &mut truncated,
    );
    (out, truncated)
}
